function remedyArt(name, group) {
  const n = name.toLowerCase().trim();
  if (ART_EXACT[n]) return { kind: ART_EXACT[n][0], col: ART_EXACT[n][1] };
  const g = (group || '').toLowerCase();
  if (/как вводить продукты/.test(g)) return { kind: 'soup', col: '#D98A3A' };
  const rules = [
    [/облепих/, 'oil', '#F08A1C'], [/тыквен/, 'oil', '#4E9A3A'], [/тмин/, 'oil', '#5A4636'], [/примул/, 'oil', '#E2B422'], [/орегано/, 'oil', '#6E9B3A'], [/расторопш.*масл|масл.*расторопш/, 'oil', '#9C7A3C'], [/масл/, 'oil', '#D6A21F'],
    [/мастик|смол/, 'resin', '#E2B13C'],
    [/dgl|солодк|корн|корен/, 'root', '#A8743E'],
    [/кисел|отвар семян|льнян|отвар/, 'kisel', '#C9A27A'],
    [/чага/, 'mushroom', '#8A5A3C'], [/кордицеп/, 'mushroom', '#C27A3A'],
    [/альгинат|фукус|водорос|ламинар/, 'algae', '#3E8E6E'],
    [/пробиот|бактери|буларди|сахаромицет|синбиот|lactobacillus/, 'probio', '#8A62D8'],
    [/вода|ессентуки|боржоми|регидрат/, 'water', '#2E8FD8'],
    [/витамин d/, 'sun', '#F2B21B'],
    [/бульон|суп/, 'soup', '#D98A3A'],
    [/вань|пилюл|му сян|хо сян/, 'pills', '#C2412E'],
    [/омепразол|ипп|антацид|лактулоз|макрогол|сенна|бисакодил|тримебутин|панкреатин|урсодезокс|первая линия|альтернативн/, 'drug', '#5D7387'],
    [/сорбент|уголь|цеолит|аминосорб/, 'tabs', '#4A4F57'],
    [/семен|семян/, 'seeds', '#9C7A3C'],
    [/псиллиум|глютамин|коллаген|лецитин|порош|пребиот|кремний/, 'powder', '#3FA7A0'],
    [/сбор|чай|ромашк|таволг/, 'tea', '#4E9A3A'],
    [/дыхан/, 'breath', '#3FA7C8'], [/спальн|ритуал|не спит/, 'moon', '#5866D6'], [/массаж|колени|велосипед/, 'move', '#E0657A'],
    [/омега/, 'caps', '#F08A1C'], [/магни/, 'tabs', '#7F8FA6'], [/цинк/, 'caps', '#5D9BB0'], [/витамин/, 'caps', '#F2A93B'],
    [/ашваганд|босвелл|артишок|трифал|чёрный орех|кора|экстракт|тулси/, 'caps', '#4E9A3A'],
    [/теанин|глицин|таурин|холин|бутират|каприл|фермент|бетаин|пепсин|минерал|хлорофилл/, 'caps', '#E0657A']
  ];
  for (const [re, kind, col] of rules) if (re.test(n)) return { kind, col };
  if (/фитотерап|сбор/.test(g)) return { kind: 'tea', col: '#4E9A3A' };
  return { kind: 'leaf', col: '#4E9A3A' };
}

