  if (has('ff') && has('c')) out.push(['no', 'Жирная рыба и углеводы не сочетаются.']);
  if (has('pf') && has('c')) out.push(['no', 'Растительные жиры и углеводы не сочетаются.']);
  if (has('ap') && has('pf')) out.push(['no', 'Растительные масла с мясом и яйцами не сочетают — жира в самом продукте достаточно.']);
  if (items.some(i => i.leg) && prot.length) out.push(['no', 'Бобовые — растительный белок, его едят отдельно от животного.']);
  if (has('fr') && (prot.length || has('ap') || has('ff'))) out.push(['no', 'Фрукты — отдельно от белка: вместе они начинают бродить.']);
  else if (has('fr') && has('c')) out.push(['soft', 'Немного ягод в кашу допустимо, но лучше есть фрукты отдельно — во второй завтрак.']);
  else if (has('fr') && veg) out.push(['soft', 'Фрукты лучше есть отдельным приёмом, а не вместе с овощами.']);
