/* ---------- doses → player blocks ---------- */
const pickRange = (a, b) => { a = Number(a); if (!b) return a; b = Number(b); return S.tier === 'b' ? a : S.tier === 'p' ? b : Math.round((a + b) / 2); };
const NUM = '(\\d+(?:\\.\\d+)?)(?:\\s*[–-]\\s*(\\d+(?:\\.\\d+)?))?';
