/* ---------- Today ---------- */
function greet() { const h = new Date().getHours(); return h < 5 ? 'Доброй ночи' : h < 12 ? 'Доброе утро' : h < 18 ? 'Добрый день' : 'Добрый вечер'; }
function lessonOfDay() {
  const t = today();
  if (S.lday && S.lday.d === t && THEORY[S.lday.id]) return S.lday.id;
  const base = TIERS[S.tier].theory;
  const list = base.filter(lessonOk).concat(Object.keys(THEORY).filter(id => (THEORY[id].sx || THEORY[id].x) && THEORY[id].t === S.tier && lessonOk(id) && !base.includes(id)));
  const id = list.find(x => !S.read[x]) || list[(kd(t).getTime() / 864e5 | 0) % list.length];
  S.lday = { d: t, id };
  saveLocal();
  return id;
}
