  openSheet(sheetHead(a[1]) + `<div class="achbig" data-on="${got ? 1 : 0}"><span class="bi">${ic(got ? a[3] : 'lock')}</span></div><p class="center">${esc(a[2])}</p><p class="small muted center">${got ? 'Получено ' + dateLong(got) : 'Пока не получено'}</p>`);
